#!/bin/bash
# 把仓库里的 pdf2zh 源文件同步到系统 python，供 pdf2zh.spec 的 collect_all('pdf2zh') 收取。
# 打 Mac 包之前必须先跑这个脚本。
set -e
REPO="$(cd "$(dirname "$0")/../.." && pwd)"
SP="$(python3 -c 'import pdf2zh,os;print(os.path.dirname(pdf2zh.__file__))')"
echo "目标: $SP"

# 两端共用的文件（源在 core/site-packages）
for f in gui_pyqt5.py ocr_pipeline.py toc_fix.py; do
  cp "$REPO/core/site-packages/pdf2zh/$f" "$SP/$f"
  echo "  共用  $f"
done

# macOS 专用的文件（源在 mac/site-packages）
for f in high_level.py; do
  cp "$REPO/mac/site-packages/pdf2zh/$f" "$SP/$f"
  echo "  Mac专用 $f"
done
echo "同步完成"
